import java.util.*;
public class UserGrouping {
    public static void main(String[] args) {
        Map<String, List<String>> userData = new HashMap<>();
        userData.put("u1", Arrays.asList("ip1", "email_domain1"));
        userData.put("u2", Arrays.asList("ip1"));
        userData.put("u3", Arrays.asList("ip2"));
        userData.put("u4", Arrays.asList("email_domain1"));
        List<Set<String>> result = findConnectedUsers(userData);
        System.out.println(result);
    }
    public static List<Set<String>> findConnectedUsers(Map<String, List<String>> userData) {
        // Map each attribute (ip or domain) to the users that have it
        Map<String, List<String>> attributeToUsers = new HashMap<>();
        for (Map.Entry<String, List<String>> entry : userData.entrySet()) {
            String user = entry.getKey();
            for (String attr : entry.getValue()) {
                attributeToUsers.computeIfAbsent(attr, k -> new ArrayList<>()).add(user);
            }
        }
        // Union-Find setup
        UnionFind uf = new UnionFind(userData.keySet());
        // Connect users that share the same attribute
        for (List<String> users : attributeToUsers.values()) {
            for (int i = 1; i < users.size(); i++) {
                uf.union(users.get(0), users.get(i));
            }
        }
        // Group users by their root parent
        Map<String, Set<String>> groups = new HashMap<>();
        for (String user : userData.keySet()) {
            String parent = uf.find(user);
            groups.computeIfAbsent(parent, k -> new HashSet<>()).add(user);
        }
        return new ArrayList<>(groups.values());
    }
}

// ---------- Helper Class ----------
class UnionFind {
    private final Map<String, String> parent = new HashMap<>();
    UnionFind(Set<String> elements) {
        for (String e : elements) parent.put(e, e);
    }
    String find(String x) {
        if (!parent.get(x).equals(x)) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }
    void union(String a, String b) {
        String pa = find(a);
        String pb = find(b);
        if (!pa.equals(pb)) parent.put(pa, pb);
    }

}
