import java.util.*;
public class UserGroupingGraph {
    public static void main(String[] args) {
        Map<String, List<String>> userData = new HashMap<>();
        userData.put("u1", Arrays.asList("ip1", "email_domain1"));
        userData.put("u2", Arrays.asList("ip1"));
        userData.put("u3", Arrays.asList("ip2"));
        userData.put("u4", Arrays.asList("email_domain1"));
        List<Set<String>> result = groupConnectedUsers(userData);
        System.out.println(result);
    }
    public static List<Set<String>> groupConnectedUsers(Map<String, List<String>> userData) {
        // Build graph: user ↔ attribute connections
        Map<String, Set<String>> graph = new HashMap<>();
        // Step 1: Build graph with user–attribute edges
        for (Map.Entry<String, List<String>> entry : userData.entrySet()) {
            String user = entry.getKey();
            for (String attr : entry.getValue()) {
                graph.computeIfAbsent(user, k -> new HashSet<>()).add(attr);
                graph.computeIfAbsent(attr, k -> new HashSet<>()).add(user);
            }
        }
        // Step 2: Traverse the graph using DFS to find connected components (users only)
        Set<String> visited = new HashSet<>();
        List<Set<String>> result = new ArrayList<>();
        for (String node : graph.keySet()) {
            // We only start DFS from user nodes (not attributes)
            if (!userData.containsKey(node) || visited.contains(node)) continue;
            Set<String> group = new HashSet<>();
            dfs(node, graph, visited, group, userData);
            result.add(group);
        }
        return result;
    }
    private static void dfs(String node, Map<String, Set<String>> graph, Set<String> visited,
        Set<String> group, Map<String, List<String>> userData) {
        visited.add(node);
        // If it's a user, add to the current group
        if (userData.containsKey(node)) {
            group.add(node);
        }
        for (String neighbor : graph.getOrDefault(node, Collections.emptySet())) {
            if (!visited.contains(neighbor)) {
                dfs(neighbor, graph, visited, group, userData);
            }
        }
    }

}
