import java.util.ArrayList;
import java.util.List;
public class SumSubarrays {
    public static List<Integer> sumSubarrays(int[] arr) {
        List<Integer> result = new ArrayList<>();
        int index = 0;
        int groupSize = 1;
        while (index < arr.length) {
            int sum = 0;
            for (int i = 0; i < groupSize \&\& index < arr.length; i++) {
                sum += arr\[index];
                index++;
            }
            result.add(sum);
            groupSize++;
        }
        return result;

    }
    public static void main(String[] args) {
        int[] arr = {1, 6, 8, 5, 9, 4, 7, 2,5,3};
        List<Integer> result = sumSubarrays(arr);
        System.out.println(result);
    }
}
Explanation:
Initialization:
result: A list to store the resulting sums.
index: An index to keep track of the current position in the array.
groupSize: A variable to keep track of the size of the current group, starting at 1.
