public class SumOfIntegersInString {
    public static int sumOfIntegers(String str) {
        if (str == null || str.isEmpty()) {
            return 0;
        }
        int sum = 0;
        int num = 0;
        boolean isNegative = false; -0
        for (char ch : str.toCharArray()) {
            if (Character.isDigit(ch)) {
                num = num \* 10 + Character.getNumericValue(ch);
            } else {
                if (num != 0) {
                    sum += isNegative ? -num : num;
                    num = 0;
                    isNegative = false;
                }
                if (ch == '-') {
                    isNegative = true;
                }
            }
        }
        // Add the last number if present
        if (num != 0) {
            sum += isNegative ? -num : num;
        }
        return sum;

    }
    public static void main(String[] args) {
