import java.util.*;
public class SortByFrequency {
    public static String sortByFrequency(String s) {
        // Step 1: Count the frequency of each character
        Map<Character, Integer> frequencyMap = new HashMap<>();
        for (char c : s.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }
        // Step 2: Create a list of characters sorted by frequency and then by alphabetical order
        List<Character> charList = new ArrayList<>(frequencyMap.keySet());
        Collections.sort(charList, (a, b) -> {
                int freqCompare = frequencyMap.get(b).compareTo(frequencyMap.get(a));
                if (freqCompare == 0) {
                    return Character.compare(a, b);
                }
                return freqCompare;
        });
        // Step 3: Build the result string
        StringBuilder result = new StringBuilder();
        for (char c : charList) {
            int count = frequencyMap.get(c);
            for (int i = 0; i < count; i++) {
                result.append(c);
            }
        }
        return result.toString();

    }
    public static void main(String[] args) {
        System.out.println(sortByFrequency("tree")); // Output: eert
        System.out.println(sortByFrequency("priti")); // Output: iiprt
        System.out.println(sortByFrequency("aacccbbb")); // Output: bbbcccaa
    }
}
