    public static int nextGreaterNumber(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int i = digits.length - 2;
        // Step 1: Find the rightmost ascent
        while (i >= 0 \&\& digits\[i] >= digits\[i + 1]) {
            i--;
        }
        // If no ascent is found, this is the highest permutation
        if (i == -1) {
            return -1;
        }
        // Step 2: Find the smallest digit larger than the ascent
        int j = digits.length - 1;
        while (digits\\\\\\\[j] <= digits\\\\\\\[i]) {
            j--;
        }
        // Step 3: Swap the digits
        swap(digits, i, j);
        // Step 4: Reverse the digits to the right of the ascent
        reverse(digits, i + 1, digits.length - 1);
        return Integer.parseInt(new String(digits));

    }
    private static void swap(char[] digits, int i, int j) {
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
    }
    private static void reverse(char[] digits, int start, int end) {
        while (start < end) {
            swap(digits, start, end);
            start++;
            end--;
        }
    }
}
