```java
import java.util.HashMap;
import java.util.Map;
public class IntegerToStringConversion {
    private static final Map<Character, String> digitToWordMap = new HashMap<>();
    static {
        digitToWordMap.put('0', "zero");
        digitToWordMap.put('1', "one");
        digitToWordMap.put('2', "two");
        digitToWordMap.put('3', "three");
        digitToWordMap.put('4', "four");
        digitToWordMap.put('5', "five");
        digitToWordMap.put('6', "six");
        digitToWordMap.put('7', "seven");
        digitToWordMap.put('8', "eight");
        digitToWordMap.put('9', "nine");
    }
    public static String convert(int number) {
        String numberString = String.valueOf(number);
        StringBuilder result = new StringBuilder();
        for (char digit : numberString.toCharArray()) {
            String word = digitToWordMap.get(digit);
            result.append(digit);
            result.append(word);
        }
        return result.toString();

    }
    public static void main(String[] args) {
        System.out.println(convert(124));    // Output: oneTwoTwoOneFour
        System.out.println(convert(14));     // Output: oneOneFour
        System.out.println(convert(7));      // Output: seven
        System.out.println(convert(5678));   // Output: fiveThreeSixTwoSevenOneEight
        System.out.println(convert(45678));  // Output: fourFourFiveThreeSixTwoSevenOneEight
    }
}
