import java.util.*;

class Booking {
    private String showName;
    private int[][] seats; // 2D array to represent seats availability
    private Set<String> bookedSeats; // Set to store booked seat numbers

    public Booking(String showName, int numRows, int numCols) {
        this.showName = showName;
        this.seats = new int[numRows][numCols];
        this.bookedSeats = new HashSet<>();
    }

    public boolean bookSeat(int row, int col) {
        if (row < 0 || row >= seats.length || col < 0 || col >= seats[0].length) {
            System.out.println("Invalid seat selection.");
            return false;
        }
        if (seats[row][col] == 1) {
            System.out.println("Seat already booked.");
            return false;
        }
        seats[row][col] = 1;
        bookedSeats.add(generateSeatNumber(row, col));
        System.out.println("Seat booked successfully: " + generateSeatNumber(row, col));
        return true;
    }

    public boolean cancelBooking(int row, int col) {
        if (row < 0 || row >= seats.length || col < 0 || col >= seats[0].length) {
            System.out.println("Invalid seat selection.");
            return false;
        }
        if (seats[row][col] == 0) {
            System.out.println("Seat not booked.");
            return false;
        }
        seats[row][col] = 0;
        bookedSeats.remove(generateSeatNumber(row, col));
        System.out.println("Booking cancelled for seat: " + generateSeatNumber(row, col));
        return true;
    }

    public void displayAvailableSeats() {
        System.out.println("Available seats for " + showName + ":");
        for (int i = 0; i < seats.length; i++) {
            for (int j = 0; j < seats[0].length; j++) {
                if (seats[i][j] == 0) {
                    System.out.print(generateSeatNumber(i, j) + " ");
                } else {
                    System.out.print("X ");
                }
            }
            System.out.println();
        }
    }

    private String generateSeatNumber(int row, int col) {
        return (row + 1) + "-" + (col + 1);
    }

    public Set<String> getBookedSeats() {
        return bookedSeats;
    }
}

public class TheaterBookingSystem {
