        Booking show1 = new Booking("Show1", 5, 5);

        show1.bookSeat(0, 0);
        show1.bookSeat(2, 2);
        show1.bookSeat(4, 4);
        show1.bookSeat(2, 2); // Duplicate booking attempt
        show1.cancelBooking(2, 2);

        show1.displayAvailableSeats();

        System.out.println("Booked seats for Show1: " + show1.getBookedSeats());
    }
}
