```java
class TreeNode {
    int val;
    TreeNode left, right;

    TreeNode(int val) {
        this.val = val;
        this.left = this.right = null;
    }
}

public class BinaryTree {
    private int totalSum = 0;

    public int sumOfPathsContainingNode(TreeNode root, int target) {
        if (root == null) {
            return 0;
        }
        totalSum = 0;
        dfs(root, target, 0, false);
        return totalSum;
    }

    private void dfs(TreeNode node, int target, int currentSum, boolean containsTarget) {
        if (node == null) {
            return;
        }

        currentSum += node.val;
        if (node.val == target) {
            containsTarget = true;
        }

        // If it's a leaf node
        if (node.left == null && node.right == null) {
            if (containsTarget) {
                totalSum += currentSum;
            }
            return;
        }

        dfs(node.left, target, currentSum, containsTarget);
        dfs(node.right, target, currentSum, containsTarget);
    }

    public static void main(String[] args) {
