```java
import java.util.LinkedList;
import java.util.Queue;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode next;

    TreeNode(int val) {
        this.val = val;
        this.left = this.right = this.next = null;
    }
}

public class ConnectNodesAtSameLevel {
    public static void connect(TreeNode root) {
        if (root == null) return;

        // Initialize a queue for level-order traversal
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            TreeNode prev = null;

            for (int i = 0; i < levelSize; i++) {
                TreeNode current = queue.poll();

                if (prev != null) {
                    prev.next = current;
                }

                prev = current;

                // Add left and right children to the queue
                if (current.left != null) {
                    queue.offer(current.left);
                }
                if (current.right != null) {
                    queue.offer(current.right);
                }
            }

            // Last node in the level should point to null
            if (prev != null) {
                prev.next = null;
            }
        }
    }

    // Helper method to print the next pointers for each level
    public static void printNextPointers(TreeNode root) {
        TreeNode levelStart = root;
        while (levelStart != null) {
            TreeNode current = levelStart;
            while (current != null) {
                System.out.print(current.val + " -> ");
                current = current.next;
            }
            System.out.println("null");
            levelStart = levelStart.left;
        }
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);
        root.left.left = new TreeNode(4);
        root.left.right = new TreeNode(5);
        root.right.left = new TreeNode(6);
        root.right.right = new TreeNode(7);

        connect(root);
        printNextPointers(root);
    }
}
