import java.util.ArrayList;
import java.util.List;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) {
        this.val = val;
        this.left = this.right = null;
    }
}

public class UniqueBinarySearchTrees {

    public static List<TreeNode> generateTrees(int n) {
        if (n == 0) {
            return new ArrayList<>();
        }
        return generateTreesHelper(1, n);
    }

    private static List<TreeNode> generateTreesHelper(int start, int end) {
        List<TreeNode> allTrees = new ArrayList<>();
        if (start > end) {
            allTrees.add(null);
            return allTrees;
        }

        for (int i = start; i <= end; i++) {
            List<TreeNode> leftTrees = generateTreesHelper(start, i - 1);
            List<TreeNode> rightTrees = generateTreesHelper(i + 1, end);

            for (TreeNode left : leftTrees) {
                for (TreeNode right : rightTrees) {
                    TreeNode currentNode = new TreeNode(i);
                    currentNode.left = left;
                    currentNode.right = right;
                    allTrees.add(currentNode);
                }
            }
        }

        return allTrees;
    }

    // Helper function to print a tree
    private static void printTree(TreeNode root, String prefix) {
        if (root == null) {
            System.out.println(prefix + "null");
            return;
        }
        System.out.println(prefix + root.val);
        printTree(root.left, prefix + "L---");
        printTree(root.right, prefix + "R---");
    }

    public static void main(String[] args) {
        int n = 3;
        List<TreeNode> trees = generateTrees(n);

        System.out.println("Unique BSTs with " + n + " nodes:");
        for (TreeNode root : trees) {
            printTree(root, "");
            System.out.println("----");
        }
    }
}
