import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

@Service
public class ApiService {

    @Autowired
    private RestTemplate restTemplate;

    public void makeApiCalls() {
        ExecutorService executorService = Executors.newFixedThreadPool(3);

        Future<?> future1 = executorService.submit(() -> {
            getProductDetails();
        });

        Future<?> future2 = executorService.submit(() -> {
            getProductPrice();
        });

        Future<?> future3 = executorService.submit(() -> {
            getProductInventory();
        });

        // Wait for all tasks to complete
        try {
            future1.get();
            future2.get();
            future3.get();
        } catch (Exception e) {
            e.printStackTrace();
        }

        executorService.shutdown();
    }

    @Retryable(value = {Exception.class}, maxAttempts = 3, backoff = @Backoff(delay = 2000))
    private void getProductDetails() {
        // Make API call to Product Details MS
    }

    @Retryable(value = {Exception.class}, maxAttempts = 3, backoff = @Backoff(delay = 2000))
    private void getProductPrice() {
        // Make API call to Product Price MS
    }

    @Retryable(value = {Exception.class}, maxAttempts = 3, backoff = @Backoff(delay = 2000))
    private void getProductInventory() {
        // Make API call to Inventory MS
    }
}
```

We have a RestTemplate bean injected using Spring's dependency injection.
We use ExecutorService to execute API calls in parallel.
We define retryable methods for each API call using @Retryable annotation from Spring Retry, specifying the maximum number of attempts and backoff delay.
The makeApiCalls method submits each API call as a task to the executor service for parallel execution and waits for their completion. If any call fails, it will be retried according to the retry configuration.
