```java
@Service
public class CurrencyService {

    private static final String API_URL = "https://api.exchangerate-api.com/v4/latest/";

    public double convert(String fromCurrency, String toCurrency, double amount) {
        RestTemplate restTemplate = new RestTemplate();
        String url = API_URL + fromCurrency;
        ResponseEntity<CurrencyResponse> response = restTemplate.getForEntity(url, CurrencyResponse.class);

        double conversionRate = response.getBody().getRates().get(toCurrency);
        return amount * conversionRate;
    }
}
```

```java
@Service
public class CurrencyService {

    private static final String API_URL = "https://api.frankfurter.app/latest";

    public double convert(String fromCurrency, String toCurrency, double amount) {
        RestTemplate restTemplate = new RestTemplate();
        String url = API_URL + "?from=" + fromCurrency + "&to=" + toCurrency;
        ResponseEntity<Map> response = restTemplate.getForEntity(url, Map.class);

        Map<String, Double> rates = (Map<String, Double>) response.getBody().get("rates");
        double conversionRate = rates.get(toCurrency);
        return amount * conversionRate;
    }
}
```

