public class Main {
    public static void main(String[] args) {
        // Singleton Pattern
        Singleton singleton = Singleton.getInstance();
        System.out.println("Singleton Instance: " + singleton);

        // Factory Pattern
        Product productA = ProductFactory.createProduct("A");
        productA.use();
        Product productB = ProductFactory.createProduct("B");
        productB.use();

        // Observer Pattern
        ConcreteSubject subject = new ConcreteSubject();
        Observer observer1 = new ConcreteObserver("Observer 1");
        Observer observer2 = new ConcreteObserver("Observer 2");
        subject.registerObserver(observer1);
        subject.registerObserver(observer2);
        subject.setMessage("Hello, World!");

        // Strategy Pattern
        Context context = new Context();
        context.setStrategy(new Addition());
        System.out.println("Addition: " + context.executeStrategy(5, 3));
        context.setStrategy(new Subtraction());
        System.out.println("Subtraction: " + context.executeStrategy(5, 3));
        context.setStrategy(new Multiplication());
        System.out.println("Multiplication: " + context.executeStrategy(5, 3));

        // Decorator Pattern
        Coffee coffee = new SimpleCoffee();
        System.out.println(coffee.getDescription() + " $" + coffee.getCost());
        coffee = new MilkDecorator(coffee);
        System.out.println(coffee.getDescription() + " $" + coffee.getCost());
        coffee = new SugarDecorator(coffee);
        System.out.println(coffee.getDescription() + " $" + coffee.getCost());
    }
}
