// src/context/ListingContext.js
import React, { createContext, useState, useContext } from 'react';

const ListingContext = createContext();

export const ListingProvider = ({ children }) => {
  const [listing, setListing] = useState(() => ({
    title: '',
    description: '',
    categoryId: '',
    price: '',
    quantity: 0,
    images: [],
    variants: [],
    shipping: {},
    status: 'draft'
  }));

  const update = (patch) => setListing(prev => ({...prev, ...patch}));
  const reset = () => setListing({ title:'', description:'', images:[], status:'draft' });

  return (
    <ListingContext.Provider value={{ listing, update, reset }}>
      {children}
    </ListingContext.Provider>
  );
};

export const useListing = () => useContext(ListingContext);
