// src/components/ListingWizard/steps/ProductInfo.jsx
import React from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { useListing } from '../../../context/ListingContext';

const schema = yup.object().shape({
  title: yup.string().required('Title is required').max(150),
  description: yup.string().required('Description is required'),
  categoryId: yup.string().required('Select category')
});

export default function ProductInfo({ onNext }) {
  const { listing, update } = useListing();
  const { register, handleSubmit, formState: { errors } } = useForm({
    defaultValues: listing,
    resolver: yupResolver(schema)
  });

  const submit = (data) => {
    update(data);
    onNext();
  };

  return (
    <form onSubmit={handleSubmit(submit)}>
      <div>
        <label>Title</label>
        <input {...register('title')} />
        {errors.title && <p role="alert">{errors.title.message}</p>}
      </div>

      <div>
        <label>Description</label>
        <textarea {...register('description')} />
        {errors.description && <p>{errors.description.message}</p>}
      </div>

      <div>
        <label>Category</label>
        <select {...register('categoryId')}>
          <option value="">Select</option>
          <option value="shoes">Shoes</option>
          <option value="apparel">Apparel</option>
        </select>
        {errors.categoryId && <p>{errors.categoryId.message}</p>}
      </div>

      <button type="submit">Next</button>
    </form>
  );
}
