// src/hooks/useImageUpload.js
import { useState } from 'react';
import axios from 'axios';

export const useImageUpload = () => {
  const [uploads, setUploads] = useState([]); // {file, progress, url, id}

  const upload = async (file, onProgress) => {
    // simple direct upload example
    const form = new FormData();
    form.append('file', file);
    const resp = await axios.post('/internal/uploads', form, {
      headers: {'Content-Type': 'multipart/form-data'},
      onUploadProgress: (ev) => {
        const pct = Math.round((ev.loaded / ev.total) * 100);
        onProgress && onProgress(pct);
      }
    });
    return resp.data; // {url, id}
  };

  return { uploads, setUploads, upload };
};
