// Conversion factors for common units
const conversionRates = {
  cupsToMilliliters: 240,
  gramsToOunces: 0.035274,
  teaspoonsToMilliliters: 4.93,
  tablespoonsToMilliliters: 14.79,
};

// Example ingredient densities (grams per milliliter)
const densities = {
  flour: 0.593,
  sugar: 0.85,
  milk: 1.03,
  butter: 0.911,
};

// Function to convert units
function convertUnits(value, fromUnit, toUnit, ingredient = null) {
  if (fromUnit === "cups" && toUnit === "milliliters") {
    return value * conversionRates.cupsToMilliliters;
  } else if (fromUnit === "grams" && toUnit === "ounces") {
    return value * conversionRates.gramsToOunces;
  } else if (ingredient && densities[ingredient]) {
    // Handle complex conversion based on density
    if (fromUnit === "grams" && toUnit === "milliliters") {
      return value / densities[ingredient];
    } else if (fromUnit === "milliliters" && toUnit === "grams") {
      return value * densities[ingredient];
    }
  }
  throw new Error(`Conversion from ${fromUnit} to ${toUnit} not supported.`);
}

// Function to scale recipes
function scaleRecipe(recipe, factor) {
  const scaledRecipe = {};
  for (const [ingredient, quantity] of Object.entries(recipe)) {
    scaledRecipe[ingredient] = quantity * factor;
  }
  return scaledRecipe;
}

