**Code Implementation**
1. App.js (Parent Component)
2. FoodList.js
3. Cart.js
4. styles.css (Optional Styling)
**How It Works**
**Food List**
Displays the list of food items with a button to add them to the cart.
Calls the addToCart function when an item is added.
**Cart**
Displays items in the cart, their count, and the total price.
Updates dynamically as items are added.
**State Management**
The cart state is managed in the App component, ensuring changes in the cart reflect across the app.

```jsx
import React, { useState } from 'react';
import FoodList from './FoodList';
import Cart from './Cart';

const App = () => {
  const [cart, setCart] = useState([]);

  const foodItems = [
    { id: 1, name: 'Pizza', price: 12.99, description: 'Cheesy and delicious' },
    { id: 2, name: 'Burger', price: 8.99, description: 'Juicy and flavorful' },
    { id: 3, name: 'Pasta', price: 10.99, description: 'Creamy and tasty' },
  ];

  // Add or update an item in the cart
  const addToCart = (item) => {
    setCart((prevCart) => {
      const existingItem = prevCart.find((cartItem) => cartItem.id === item.id);

      if (existingItem) {
        return prevCart.map((cartItem) =>
          cartItem.id === item.id
            ? { ...cartItem, count: cartItem.count + 1 }
            : cartItem
        );
      }

      return [...prevCart, { ...item, count: 1 }];
    });
  };

  return (
    <div>
      <h1>Food Menu</h1>
      <FoodList foodItems={foodItems} onAddToCart={addToCart} />
      <Cart cartItems={cart} />
    </div>
  );
};

export default App;
```

